import {voiceCapture,voiceDescription,preferVoiceCodec,tuneVoiceSender} from './voice-quality.mjs';
import {VoiceLevels} from './voice-levels.mjs';
const uid=()=>crypto.randomUUID().replaceAll('-','');
const icon=on=>`<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8"/>${on?'':'<path d="m3 3 18 18"/>'}</svg>`;
export class RoomVoice{
 constructor(rooms){this.rooms=rooms;this.alive=true;this.muted=true;this.peers=new Map();this.seen=new Set();this.out=[];this.session=uid();this.levels=new VoiceLevels();this.members=[];this.pagehide=()=>this.destroy();window.addEventListener('pagehide',this.pagehide);this.unlock=()=>{this.levels.resume();for(const p of this.peers.values())this.play(p)};window.addEventListener('pointerdown',this.unlock,{capture:true})}
 attach(button){this.button=button;button.onclick=()=>this.toggle();this.paint();if(!this.started){this.started=true;this.exchange().catch(()=>{});this.schedule()}}
 paint(){const b=this.button;if(!b)return;b.innerHTML=icon(!this.muted)+`<span>${this.busy?'连接中':this.muted?'开麦':'关麦'}</span>`;b.dataset.voiceState=this.muted?'off':'on';b.setAttribute('aria-pressed',String(!this.muted));b.setAttribute('aria-label',this.muted?'打开麦克风，与同桌玩家聊天':'关闭麦克风');const opened=this.members.filter(m=>m.session!==this.session&&!m.muted),connected=opened.filter(m=>this.peers.get(m.session)?.pc.connectionState==='connected');b.title=this.muted?'开启同桌语音':opened.length===0?'麦克风已开启 · 等待同桌开麦':`麦克风已开启 · 语音连接 ${connected.length}/${opened.length}`;b.dataset.voiceConnection=opened.some(m=>this.peers.get(m.session)?.warned)?'failed':connected.length<opened.length?'connecting':'ready';if(!this.muted&&!this.busy&&connected.length<opened.length)b.querySelector('span').textContent=b.dataset.voiceConnection==='failed'?'关麦 · 未连通':'关麦 · 连接中';b.disabled=!!this.busy}
 async toggle(){if(this.busy||!this.alive)return;this.busy=true;this.paint();try{
 if(!this.muted){this.muted=true;this.stream?.getTracks().forEach(t=>t.stop());this.stream=null;this.levels.remove(this.session);this.indicators();for(const p of this.peers.values())await p.sender?.replaceTrack(null);await this.exchange()}
 else{this.levels.resume();if(!navigator.mediaDevices?.getUserMedia||!globalThis.RTCPeerConnection)throw Error('当前浏览器暂不支持语音，请用最新版浏览器打开');const stream=await navigator.mediaDevices.getUserMedia(voiceCapture);if(!this.alive){stream.getTracks().forEach(t=>t.stop());return}this.stream=stream;this.muted=false;this.levels.bind(this.session,stream);this.indicators();for(const [id,p]of this.peers){await p.sender?.replaceTrack(stream.getAudioTracks()[0]);await tuneVoiceSender(p.sender);if(p.pc.connectionState==='failed')await this.recover(id,p)}for(const p of this.peers.values())this.play(p);await this.exchange();if(!this.timer)this.schedule()}
 }catch(e){this.muted=true;this.stream?.getTracks().forEach(t=>t.stop());this.stream=null;this.rooms.toast(e.name==='NotAllowedError'?'请允许麦克风权限后再开麦':e.message)}finally{this.busy=false;this.paint();this.indicators()}}
 schedule(){clearTimeout(this.timer);if(this.alive)this.timer=setTimeout(async()=>{try{await this.exchange()}catch(e){if(!this.failed){this.rooms.toast('语音连接暂时中断，正在重连');this.failed=true}}this.schedule()},1500)}
 async exchange(){if(this.exchanging||!this.alive)return;this.exchanging=true;try{const signal=this.out[0];const data=await this.rooms.api('/api/rooms/'+this.rooms.id+'/voice',{session:this.session,muted:this.muted,...(signal?{signal}:{})});if(!this.alive)return;if(signal)this.out.shift();this.failed=false;this.members=data.members;this.paint();this.indicators();const members=data.members.filter(m=>m.session!==this.session);const live=new Set(members.map(m=>m.session));for(const [id,p]of this.peers)if(!live.has(id)){p.pc.close();p.audio.remove();this.levels.remove(id);this.peers.delete(id)}for(const m of members)if(!this.peers.has(m.session)){const p=this.peer(m.session);if(this.session<m.session)await this.offer(m.session,p)}for(const message of data.messages){if(this.seen.has(message.id))continue;const p=this.peers.get(message.from);if(!p)continue;const v=message.payload;if(v.type==='restart'){if(this.session<message.from)await this.recover(message.from,p)}else if(v.type==='candidate'){if(p.pc.remoteDescription)await this.candidate(p,v.candidate);else p.candidates.push(v.candidate)}else{await p.pc.setRemoteDescription({type:v.type,sdp:v.sdp});if(v.type==='offer'){const transceiver=p.pc.getTransceivers().find(t=>t.mid!==null);if(transceiver){transceiver.direction='sendrecv';preferVoiceCodec(transceiver);p.sender=transceiver.sender;await p.sender.replaceTrack(this.stream?.getAudioTracks()[0]??null)}}for(const c of p.candidates.splice(0))await this.candidate(p,c);if(v.type==='offer'){await p.pc.setLocalDescription(voiceDescription(await p.pc.createAnswer()));await tuneVoiceSender(p.sender);this.queue(message.from,{type:'answer',sdp:p.pc.localDescription.sdp})}else if(v.type==='answer')await tuneVoiceSender(p.sender)}this.seen.add(message.id)}for(const [id,p]of this.peers)if(p.pc.connectionState!=='connected'&&Date.now()-p.created>18000)await this.recover(id,p);if(this.seen.size>600)this.seen=new Set([...this.seen].slice(-400));}catch(e){if(e.message?.includes('对方已离开语音'))this.out.shift();throw e}finally{this.exchanging=false}}
 peer(id){const pc=new RTCPeerConnection({iceServers:[{urls:'stun:stun.cloudflare.com:3478'}]}),audio=document.createElement('audio');audio.autoplay=true;audio.setAttribute('playsinline','');audio.hidden=true;document.body.append(audio);const p={pc,audio,candidates:[],created:Date.now(),attempts:0,nextRetry:0,sender:this.session<id?pc.addTransceiver(this.stream?.getAudioTracks()[0]??'audio',{direction:'sendrecv'}).sender:null};for(const transceiver of pc.getTransceivers())preferVoiceCodec(transceiver);pc.onicecandidate=e=>{if(e.candidate)this.queue(id,{type:'candidate',candidate:e.candidate.toJSON()})};pc.ontrack=e=>{audio.srcObject=e.streams[0]??new MediaStream([e.track]);this.levels.bind(id,audio.srcObject);this.play(p)};pc.onconnectionstatechange=()=>{if(pc.connectionState==='connected'){p.attempts=0;p.warned=false;tuneVoiceSender(p.sender);this.play(p)}if(pc.connectionState==='failed')this.recover(id,p).catch(()=>{});this.paint()};this.peers.set(id,p);return p}
 async play(p){if(!p.audio.srcObject)return;try{await p.audio.play();p.playBlocked=false}catch{if(!p.playBlocked){p.playBlocked=true;this.rooms.toast('语音播放被浏览器暂停，点击牌桌任意按钮恢复')}}}
 async offer(id,p,restart=false){if(p.offering||!this.alive)return;p.offering=true;try{if(p.pc.signalingState==='have-local-offer')await p.pc.setLocalDescription({type:'rollback'});if(p.pc.signalingState!=='stable')return;await p.pc.setLocalDescription(voiceDescription(await p.pc.createOffer(restart?{iceRestart:true}:{})));this.queue(id,{type:'offer',sdp:p.pc.localDescription.sdp})}finally{p.offering=false}}
 async recover(id,p){if(!this.alive||p.pc.connectionState==='closed'||Date.now()<p.nextRetry)return;if(p.attempts>=3){if(!p.warned){p.warned=true;this.rooms.toast('麦克风已开启，但语音网络未连通；不同网络可能需要中继服务')}return}p.attempts++;p.nextRetry=Date.now()+15000;if(this.session<id)await this.offer(id,p,true);else this.queue(id,{type:'restart'});this.paint()}
 async candidate(p,c){try{await p.pc.addIceCandidate(c)}catch(e){if(e.name!=='OperationError')throw e /* Ignore stale ICE candidates from a previous connection attempt. */}}
 queue(to,payload){if(this.alive){this.out.push({id:uid(),to,payload});clearTimeout(this.flushTimer);this.flushTimer=setTimeout(()=>this.flush(),0)}}
 async flush(){if(!this.alive||!this.out.length)return;if(this.exchanging){this.flushTimer=setTimeout(()=>this.flush(),100);return}try{await this.exchange()}catch{}if(this.out.length)this.flushTimer=setTimeout(()=>this.flush(),200)}
 labels(host,r){if(!r||!this.alive)return;this.host=host;this.r=r;const actions=host.querySelector('.gd-end .gd-result > div')??host.querySelector('.mp-action-row')??host.querySelector('.mp-controls,.gd-actions,.craps-heading,.rl-heading');if(actions){let button=host.querySelector('[data-room-mic]')??this.button;if(!button){const holder=document.createElement('span');holder.innerHTML=voiceButton();button=holder.firstElementChild}if(button.parentNode!==actions)actions.insertBefore(button,actions.querySelector(':scope > button'));this.attach(button)}this.indicators();if(!this.meterTimer)this.meterTimer=setInterval(()=>{if(!document.hidden)this.indicators()},150)}
 indicators(){if(!this.host||!this.r)return;for(let i=0;i<this.r.seats.length;i++){const own=i===this.r.you,seat=this.r.seats[i],member=own?{session:this.session,muted:this.muted}:this.members.find(m=>m.id===seat.id),relative=(i-this.r.you+this.r.seats.length)%this.r.seats.length;const label=this.host.querySelector(`[data-voice-seat="${i}"]`)??(own?this.host.querySelector('.mp-own > strong,.gd-hand-heading > b'):this.host.querySelector(`[data-seat-label="${relative}"] > strong`));if(!label)continue;let meter=label.querySelector('[data-voice-meter]');if(!member||member.muted){meter?.remove();continue}if(!meter){if(!own&&label.firstChild?.nodeType===3){const name=document.createElement('span');name.className='voice-player-name';name.textContent=label.firstChild.textContent;label.firstChild.replaceWith(name)}meter=document.createElement('span');meter.dataset.voiceMeter=seat.id;meter.className='mp-voice-meter';meter.innerHTML='<span class="voice-dot"></span><i></i><i></i><i></i>';label.append(meter)}const peer=this.peers.get(member.session),source=peer?.pc.getReceivers().find(x=>x.track?.kind==='audio')?.getSynchronizationSources?.()[0];const volume=source?.audioLevel??this.levels.level(member.session);meter.dataset.speaking=String(volume>.015);meter.title=volume>.015?'正在说话':'麦克风已开启';meter.setAttribute('aria-label',meter.title);const bars=meter.querySelectorAll('i');for(let j=0;j<bars.length;j++)bars[j].style.height=Math.round(3+Math.min(1,volume*7)*[7,12,9][j])+'px'} }
 destroy(){if(!this.alive)return;this.alive=false;clearTimeout(this.timer);clearTimeout(this.flushTimer);clearInterval(this.meterTimer);this.levels.destroy();this.stream?.getTracks().forEach(t=>t.stop());for(const p of this.peers.values()){p.pc.close();p.audio.srcObject=null;p.audio.remove()}this.peers.clear();window.removeEventListener('pagehide',this.pagehide);window.removeEventListener('pointerdown',this.unlock,{capture:true});if(this.timer)fetch('/api/rooms/'+this.rooms.id+'/voice',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({session:this.session,leave:true}),keepalive:true}).catch(()=>{})}
}
export function voiceButton(){return `<button type="button" class="mp-voice-button" data-room-mic aria-pressed="false" aria-label="打开麦克风，与同桌玩家聊天">${icon(false)}<span>开麦</span></button>`}
